        return as_json({
            "order": order.id,
            "date": order.date.isoformat(),
            "customer": order.customer,
            "lines": [
                {
                    "sku": l.sku,
                    "quantity": l.quantity,
                    "unit": amount(l.unit),
                    "gross": amount(l.gross),
                    "discount": amount(l.discount),
                    "net": amount(l.net),
                }
